import{_ as A,l as i,o as e,c as l,v as r,p as s,x as t,d as n,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"无锁与 ABA","description":"","frontmatter":{"title":"无锁与 ABA","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/lockfree-aba.md","filePath":"cs/lockfree-aba.md","lastUpdated":1789023840000}'),h={name:"cs/lockfree-aba.md"};function p(B,a,m,_,C,E){const o=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=r('<h1 id="无锁与-aba" tabindex="-1">无锁与 ABA <a class="header-anchor" href="#无锁与-aba" aria-label="Permalink to &quot;无锁与 ABA&quot;">​</a></h1><div class="epigraph"><p>CAS 成功只说明字里又出现了期望的位型；它不说明你第一次看见的那个对象还活着——这就是 ABA。</p><footer>—— 据 Michael, Hazard Pointers, PODC 2004；Herlihy 无锁文献整理</footer></div><p><a href="/cs/rcu-gp">上一课</a>让 RCU 用宽限期避免「指针还在手里、结点已释放」。无锁栈用 CAS 改头指针，往往自己回收结点。缺口是 <strong>ABA</strong>：头从 A 变为 B 再变回 A，CAS 仍成功，链却已乱。本课钉现象与对策直觉（版本戳、Hazard Pointer、或继续用 RCU），不写可运行的攻击构造。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>无锁：某个线程的延迟不阻止其它线程完成操作（无锁进度）。实现常用<a href="/cs/atomic-rmw">原子 CAS</a> 循环。弹出栈：读头 A，读 A→next，CAS 头从 A 到 next。其间另一线程弹出 A、再弹出更多、又把 A 分配回来当头——CAS 看见头仍是 A，成功，但 A→next 已是过期值。缺口不是宽限期定义，而是 <strong>CAS 匹配 ≠ 同一代对象</strong>。</p><p><span class="marginnote">加标签：指针旁存版本计数，CAS 双字，使复用 A 时标签不同。Hazard Pointer：读者先公布「我正拿着这些指针」，回收者跳过。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>教学承认三条路：(1) 不回收或延迟回收（RCU/epoch）；(2) 指针打标签；(3) 冒险指针。内核链表多走 (1)。用户无锁队列要显式选。进度：无锁不等于无等待；CAS 可活锁式重试——下一组课的活锁会再点。</p>',8)),(e(),s(c,null,{default:t(()=>[d(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20CAS%5B%22CAS%20%E5%A4%B4%E4%BB%8E%20A%20%E5%88%B0%20next%22%5D%20--%3E%20OK%5B%22%E7%9C%9F%E7%9A%84%E8%BF%98%E6%98%AF%E5%BD%93%E5%88%9D%E9%82%A3%E6%AC%A1%20A%22%5D%0A%20%20CAS%20--%3E%20ABA%5B%22A%20%E8%A2%AB%E5%A4%8D%E7%94%A8%3A%20%E4%BD%8D%E5%9E%8B%E7%9B%B8%E5%90%8C%E7%BB%93%E6%9E%84%E5%B7%B2%E5%8F%98%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>与<a href="/cs/memory-barrier-os">内存屏障</a>：CAS 成功仍要规定节点内容何时可见。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>ABA 说明无锁正确性不能只靠「最终 CAS 成功」。RCU 的 GP 是解决「结点不能复用得太早」的一种；打标签解决「同一地址不同代」。两者都比「裸 CAS 换头」重一点，但这是正确性税。不要在教学里用具体释放后立刻 malloc 的时序当习题去复现损坏——理解结构即可。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不给可编译的无锁栈完整实现当作业答案，不讨论如何利用 ABA 打堆。死锁四条件处理的是锁上的永久等待，对象不同，下一课。</p><p>后课默认：无锁仍有 ABA 与活锁重试。锁上的永久互等，下一课<a href="/cs/deadlock-coffman">死锁四个条件</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>无锁常用 CAS；ABA 是复用使位型碰巧相同。</li><li>对策：延迟回收、打标签、Hazard Pointer。</li><li>锁上的死锁是下一课。</li><li>出处：Michael, <em>Hazard Pointers</em>, PODC 2004；Herlihy 无锁进度定义。</li></ul>',8))])}const u=A(h,[["render",p]]);export{S as __pageData,u as default};
